# Snippet 1: Define cascade computation and evaluate three candidate upgrades

alpha = 0.2

def cascade_final_largest_size(u, v):
    # Start from the initial grid, add the candidate line, compute initial loads/capacities
    H = G.copy()
    if not H.has_edge(u, v):
        H.add_edge(u, v)

    # Initial loads and capacities computed on the modified grid
    loads_initial = nx.betweenness_centrality(H, normalized=False)
    capacities = {n: (1.0 + alpha) * loads_initial[n] for n in H.nodes()}

    # Trigger line removal: remove the line between 48 and 68
    if H.has_edge(48, 68):
        H_trigger = H.copy()
        H_trigger.remove_edge(48, 68)
    elif H.has_edge(68, 48):
        H_trigger = H.copy()
        H_trigger.remove_edge(68, 48)
    else:
        H_trigger = H.copy()  # If the line isn't present for some reason

    current = H_trigger.copy()

    # Cascade: repeatedly remove overloaded buses
    while True:
        if current.number_of_nodes() == 0:
            break
        loads = nx.betweenness_centrality(current, normalized=False)
        to_fail = {n for n in current.nodes() if loads.get(n, 0) > capacities.get(n, 0)}
        if not to_fail:
            break
        current.remove_nodes_from(to_fail)

    # Determine size of the largest surviving component
    if current.number_of_nodes() == 0:
        final_size = 0
    else:
        largest = max(nx.connected_components(current), key=len)
        final_size = len(largest)

    return final_size

candidates = [(31, 81), (23, 76), (48, 82)]
results = {}
for a, b in candidates:
    size = cascade_final_largest_size(a, b)
    results[(a, b)] = size
    print(f"Candidate edge {a}-{b}: final largest component size = {size}")

# Also print a quick summary of the best candidate
best_edge = max(results, key=lambda k: results[k])
print("Best candidate:", best_edge, "with size", results[best_edge])

